<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-2: #eef3f9;
        --text: #17212b;
        --muted: #5f6b7a;
        --border: #d8e0ea;
        --accent: #2f6bff;
        --accent-strong: #2457d6;
        --shadow: 0 20px 60px rgba(23, 33, 43, 0.12);
        --radius-xl: 28px;
        --radius-lg: 18px;
        --radius-md: 14px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, #ffffff 0%, var(--bg) 46%, #e9eef6 100%);
        color: var(--text);
        line-height: 1.6;
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-180%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface);
        border: 1px solid var(--border);
        box-shadow: var(--shadow);
        text-decoration: none;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        padding: 5rem 1.25rem 3rem;
      }

      .shell {
        width: min(100%, 920px);
        margin: 0 auto;
      }

      .hero {
        background: linear-gradient(135deg, rgba(47, 107, 255, 0.12), rgba(255, 255, 255, 0.92));
        border: 1px solid var(--border);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 2.5rem);
        margin-bottom: 1.25rem;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: var(--surface);
        border: 1px solid var(--border);
        color: var(--accent-strong);
        font-weight: 700;
        font-size: 0.9rem;
      }

      h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2.2rem, 5vw, 4rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lead {
        max-width: 60ch;
        margin: 0;
        color: var(--muted);
        font-size: 1.05rem;
      }

      .faq-list {
        display: grid;
        gap: 0.9rem;
      }

      .example {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: var(--radius-lg);
        box-shadow: 0 10px 30px rgba(23, 33, 43, 0.06);
        overflow: hidden;
      }

      .example[open] {
        border-color: rgba(47, 107, 255, 0.35);
      }

      .example > summary {
        list-style: none;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.1rem 1.25rem;
        font-weight: 700;
        font-size: 1.05rem;
      }

      .example > summary::-webkit-details-marker {
        display: none;
      }

      .example > summary::after {
        content: "+";
        display: grid;
        place-items: center;
        width: 2rem;
        height: 2rem;
        border-radius: 999px;
        background: var(--surface-2);
        color: var(--accent-strong);
        flex: none;
        transition: transform 180ms ease, background-color 180ms ease;
      }

      .example[open] > summary::after {
        content: "–";
        transform: rotate(0deg);
        background: #dbe6ff;
      }

      .example > summary:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: -3px;
      }

      .details {
        padding: 0 1.25rem 1.25rem;
        color: var(--muted);
      }

      .details p {
        margin: 0;
      }

      .details p + p {
        margin-top: 0.85rem;
      }

      .details strong {
        color: var(--text);
      }

      @media (min-width: 720px) {
        main {
          padding-inline: 1.5rem;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: Highlight;
          --accent-strong: HighlightText;
        }

        .hero,
        .example,
        .skip-link {
          forced-color-adjust: auto;
          box-shadow: none;
        }

        .example > summary::after {
          border: 1px solid ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <div class="shell">
        <section class="hero" aria-labelledby="page-title">
          <div class="eyebrow">Cat FAQ</div>
          <h1 id="page-title">Everything people ask about cats</h1>
          <p class="lead">
            A calm, friendly guide to cat behavior, care, and the little mysteries that make felines such
            compelling companions.
          </p>
        </section>

        <section class="faq-list" aria-label="Frequently asked questions about cats" id="faq-root"></section>
      </div>
    </main>

    <script>
      const faqs = [
        {
          question: "Why do cats sleep so much?",
          answer: [
            "Cats are natural energy conservers. A lot of their day is spent resting so they can burst into short periods of play, hunting, and exploration.",
            "Adult cats often sleep 12 to 16 hours a day, and kittens or senior cats may sleep even more."
          ]
        },
        {
          question: "How can I tell if a cat is happy?",
          answer: [
            "Look for relaxed body language: a softly held tail, slow blinking, kneading, gentle rubbing, and a cat that chooses to stay nearby.",
            "A content cat usually eats normally, grooms itself, and engages in play or curiosity at its own pace."
          ]
        },
        {
          question: "Do cats need baths?",
          answer: [
            "Most healthy cats do a good job grooming themselves and do not need regular baths.",
            "Baths are usually only needed for specific situations such as a dirty coat, skin treatment, or a cat that cannot groom safely."
          ]
        },
        {
          question: "Why do cats purr?",
          answer: [
            "Purring is often linked to comfort and connection, but cats may also purr when they are nervous, recovering, or asking for attention.",
            "The sound is not always a simple sign of happiness; it is one of the ways cats communicate."
          ]
        },
        {
          question: "What kind of toys do cats like best?",
          answer: [
            "Many cats enjoy toys that mimic prey movement, like wand toys, rolling balls, and small objects they can stalk and pounce on.",
            "Variety helps. Rotate toys every so often so the experience stays fresh and interesting."
          ]
        },
        {
          question: "How do I make a new cat feel at home?",
          answer: [
            "Start with one quiet room that includes food, water, a litter box, hiding spots, and a comfortable bed.",
            "Move slowly, keep routines predictable, and let the cat choose when to explore the rest of the home."
          ]
        }
      ];

      function FAQItem({ question, answer }) {
        return `
          <details class="example">
            <summary>${question}</summary>
            <div class="details">
              ${answer.map((paragraph) => `<p>${paragraph}</p>`).join("")}
            </div>
          </details>
        `;
      }

      function App() {
        return faqs.map(FAQItem).join("");
      }

      document.getElementById("faq-root").innerHTML = App();
    </script>
  </body>
</html>
